-- =============================================================================
-- Zoe (My Space Staff Assistant) — Prompt 3: Department Teaching Loop,
-- 200+ Curated Knowledge Base with Synonym FTS & Usage Tracking, Guaranteed
-- Learning Log Recording, Opt-In Web Push Cap (2/day), and Role Goals Dashboard
-- Version: 20261031160000 (unique across supabase/migrations/ and schema_migrations)
-- =============================================================================

-- 1. Extend `staff_assistant_unanswered` for Department Teaching Loop & Asker Notification
ALTER TABLE public.staff_assistant_unanswered
  ADD COLUMN IF NOT EXISTS routed_department text NOT NULL DEFAULT 'general',
  ADD COLUMN IF NOT EXISTS taught_knowledge_id uuid REFERENCES public.staff_assistant_knowledge_base(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS taught_by_name text,
  ADD COLUMN IF NOT EXISTS taught_at timestamptz,
  ADD COLUMN IF NOT EXISTS asker_notified_at timestamptz,
  ADD COLUMN IF NOT EXISTS asker_seen_at timestamptz;

CREATE INDEX IF NOT EXISTS idx_staff_assistant_unanswered_dept_status
  ON public.staff_assistant_unanswered (routed_department, status, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_staff_assistant_unanswered_user_taught
  ON public.staff_assistant_unanswered (user_id, taught_at DESC)
  WHERE taught_knowledge_id IS NOT NULL;

-- Backfill routed_department on existing unanswered rows from caller_roles / question_text
UPDATE public.staff_assistant_unanswered
SET routed_department = CASE
  WHEN question_text ILIKE '%call%' OR question_text ILIKE '%jane%' OR question_text ILIKE '%winnie%' OR question_text ILIKE '%hanisha%' THEN 'calling_center'
  WHEN question_text ILIKE '%arrears%' OR question_text ILIKE '%first 7%' OR question_text ILIKE '%tenant%' THEN 'tenant_ops'
  WHEN question_text ILIKE '%landlord%' OR question_text ILIKE '%lc1%' THEN 'landlord_ops'
  WHEN question_text ILIKE '%receivables%' OR question_text ILIKE '%payables%' OR question_text ILIKE '%treasury%' OR question_text ILIKE '%cash%' THEN 'financial_ops'
  WHEN question_text ILIKE '%coo%' OR question_text ILIKE '%coverage%' THEN 'coo_ceo'
  WHEN 'tenant_ops' = ANY(caller_roles) THEN 'tenant_ops'
  WHEN 'landlord_ops' = ANY(caller_roles) THEN 'landlord_ops'
  WHEN 'agent_ops' = ANY(caller_roles) THEN 'agent_ops'
  WHEN 'partner_ops' = ANY(caller_roles) THEN 'partner_ops'
  WHEN 'financial_ops' = ANY(caller_roles) OR 'cfo' = ANY(caller_roles) THEN 'financial_ops'
  WHEN 'hr' = ANY(caller_roles) THEN 'hr'
  ELSE 'general'
END
WHERE routed_department = 'general';

-- 2. Extend `staff_assistant_knowledge_base` for Department Lead Attribution,
--    90-Day Review Expiry, Synonym Expansion, and Usage Tracking
ALTER TABLE public.staff_assistant_knowledge_base
  ADD COLUMN IF NOT EXISTS department text NOT NULL DEFAULT 'general',
  ADD COLUMN IF NOT EXISTS reviewed_by_name text NOT NULL DEFAULT 'Department Lead',
  ADD COLUMN IF NOT EXISTS expires_at timestamptz NOT NULL DEFAULT (now() + interval '90 days'),
  ADD COLUMN IF NOT EXISTS synonyms text[] NOT NULL DEFAULT '{}'::text[],
  ADD COLUMN IF NOT EXISTS usage_count integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS last_used_at timestamptz,
  ADD COLUMN IF NOT EXISTS source_unanswered_id uuid REFERENCES public.staff_assistant_unanswered(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_staff_assistant_kb_dept_status
  ON public.staff_assistant_knowledge_base (department, review_status, expires_at);

CREATE INDEX IF NOT EXISTS idx_staff_assistant_kb_usage
  ON public.staff_assistant_knowledge_base (usage_count DESC, last_used_at DESC);

-- Track KB searches that find 0 entries (topic + sanitized keywords only, no PII)
CREATE TABLE IF NOT EXISTS public.staff_assistant_kb_zero_hits (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  caller_roles text[] NOT NULL DEFAULT '{}'::text[],
  sanitized_query text NOT NULL CHECK (char_length(btrim(sanitized_query)) BETWEEN 2 AND 240),
  routed_department text NOT NULL DEFAULT 'general',
  hit_count integer NOT NULL DEFAULT 1,
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_staff_assistant_kb_zero_hits_dept
  ON public.staff_assistant_kb_zero_hits (routed_department, hit_count DESC, last_seen_at DESC);

ALTER TABLE public.staff_assistant_kb_zero_hits ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE public.staff_assistant_kb_zero_hits FROM PUBLIC, anon;
GRANT SELECT, INSERT, UPDATE ON TABLE public.staff_assistant_kb_zero_hits TO authenticated;

DROP POLICY IF EXISTS "mfa_required_for_staff" ON public.staff_assistant_kb_zero_hits;
CREATE POLICY "mfa_required_for_staff"
  ON public.staff_assistant_kb_zero_hits
  AS RESTRICTIVE
  FOR ALL
  TO authenticated
  USING (
    public.staff_assistant_has_access()
    AND COALESCE((SELECT auth.jwt() ->> 'aal'), 'aal1') = 'aal2'
  )
  WITH CHECK (
    public.staff_assistant_has_access()
    AND COALESCE((SELECT auth.jwt() ->> 'aal'), 'aal1') = 'aal2'
  );

DROP POLICY IF EXISTS "staff_assistant_kb_zero_hits_reviewer_or_owner" ON public.staff_assistant_kb_zero_hits;
CREATE POLICY "staff_assistant_kb_zero_hits_reviewer_or_owner"
  ON public.staff_assistant_kb_zero_hits
  FOR ALL
  TO authenticated
  USING (
    user_id = (SELECT auth.uid())
    OR public.staff_assistant_crm_can_review()
  )
  WITH CHECK (
    user_id = (SELECT auth.uid())
    OR public.staff_assistant_crm_can_review()
  );

-- 3. Extend `staff_assistant_preferences` for Opt-In Web Push (capped at 2/day) & First-Time Tour
ALTER TABLE public.staff_assistant_preferences
  ADD COLUMN IF NOT EXISTS web_push_enabled boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS web_push_muted boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS web_push_sent_today_count integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS web_push_sent_kampala_date date,
  ADD COLUMN IF NOT EXISTS has_completed_tour boolean NOT NULL DEFAULT false;

-- Enforce at most 2 web push notifications per staff member per Kampala day
CREATE OR REPLACE FUNCTION public.staff_assistant_can_send_web_push(
  p_user_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_today date := (now() AT TIME ZONE 'Africa/Kampala')::date;
  v_prefs public.staff_assistant_preferences;
  v_count integer;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'missing_user');
  END IF;

  SELECT * INTO v_prefs
  FROM public.staff_assistant_preferences
  WHERE user_id = p_user_id;

  IF v_prefs.user_id IS NULL OR NOT v_prefs.web_push_enabled OR v_prefs.web_push_muted THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'opt_in_disabled_or_muted');
  END IF;

  v_count := CASE
    WHEN v_prefs.web_push_sent_kampala_date = v_today THEN COALESCE(v_prefs.web_push_sent_today_count, 0)
    ELSE 0
  END;

  IF v_count >= 2 THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'daily_cap_reached', 'sent_today', v_count);
  END IF;

  UPDATE public.staff_assistant_preferences
  SET
    web_push_sent_kampala_date = v_today,
    web_push_sent_today_count = v_count + 1,
    updated_at = now()
  WHERE user_id = p_user_id;

  RETURN jsonb_build_object('allowed', true, 'sent_today', v_count + 1, 'daily_cap', 2);
END;
$$;

REVOKE ALL ON FUNCTION public.staff_assistant_can_send_web_push(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.staff_assistant_can_send_web_push(uuid) TO authenticated;

-- 4. Backfill `staff_assistant_learning_log` from historical assistant turns so it is never 0 rows,
--    and provide `staff_assistant_record_learning_turn` for guaranteed per-turn logging.
INSERT INTO public.staff_assistant_learning_log (
  message_id,
  conversation_id,
  user_id,
  caller_roles,
  topic,
  tool_used,
  outcome,
  latency_ms,
  cost_usd,
  model_tier,
  created_at
)
SELECT
  m.id,
  m.conversation_id,
  m.user_id,
  ARRAY['staff']::text[],
  CASE
    WHEN 'get_hr_calling_detailed_report' = ANY(m.tools_called) THEN 'calling_center'
    WHEN 'get_welile_glossary' = ANY(m.tools_called) OR 'get_staff_manual_help' = ANY(m.tools_called) THEN 'welile_glossary_process'
    ELSE 'general_accounting_writing'
  END,
  m.tools_called[1],
  COALESCE(m.outcome, 'answered'),
  m.latency_ms,
  COALESCE(m.cost_usd, 0),
  'fast',
  m.created_at
FROM public.staff_assistant_messages m
WHERE m.role = 'assistant'
  AND NOT EXISTS (
    SELECT 1
    FROM public.staff_assistant_learning_log l
    WHERE l.message_id = m.id
  );

-- 5. Teaching Loop RPCs: Department Queue, Teach/Approve Entry, and Asker Notification
CREATE OR REPLACE FUNCTION public.staff_assistant_department_teaching_queue(
  p_department text DEFAULT NULL,
  p_status text DEFAULT 'open',
  p_limit integer DEFAULT 50
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := (SELECT auth.uid());
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
  v_dept text := NULLIF(LOWER(btrim(COALESCE(p_department, ''))), '');
  v_status text := NULLIF(LOWER(btrim(COALESCE(p_status, 'open'))), '');
  v_items jsonb;
  v_zero_hits jsonb;
BEGIN
  IF v_uid IS NULL OR NOT public.staff_assistant_crm_can_review() THEN
    RAISE EXCEPTION 'Not authorized: department lead or reviewer role required.'
      USING ERRCODE = '42501';
  END IF;

  WITH queue_rows AS (
    SELECT
      u.id,
      u.routed_department,
      u.reason,
      COALESCE(u.error_code, 'ERR_UNANSWERED') AS error_code,
      public.staff_assistant_redact_text(u.question_text) AS redacted_question,
      u.caller_roles,
      u.status,
      u.taught_knowledge_id,
      u.taught_by_name,
      u.taught_at,
      u.created_at
    FROM public.staff_assistant_unanswered u
    WHERE (v_dept IS NULL OR u.routed_department = v_dept)
      AND (v_status IS NULL OR v_status = 'all' OR u.status = v_status)
    ORDER BY u.created_at DESC
    LIMIT v_limit
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(queue_rows)), '[]'::jsonb)
  INTO v_items
  FROM queue_rows;

  WITH zero_rows AS (
    SELECT
      z.id,
      z.routed_department,
      z.sanitized_query,
      z.hit_count,
      z.last_seen_at
    FROM public.staff_assistant_kb_zero_hits z
    WHERE (v_dept IS NULL OR z.routed_department = v_dept)
    ORDER BY z.hit_count DESC, z.last_seen_at DESC
    LIMIT 25
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(zero_rows)), '[]'::jsonb)
  INTO v_zero_hits
  FROM zero_rows;

  RETURN jsonb_build_object(
    'items', COALESCE(v_items, '[]'::jsonb),
    'zero_hit_queries', COALESCE(v_zero_hits, '[]'::jsonb)
  );
END;
$$;

REVOKE ALL ON FUNCTION public.staff_assistant_department_teaching_queue(text, text, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.staff_assistant_department_teaching_queue(text, text, integer) TO authenticated;

CREATE OR REPLACE FUNCTION public.staff_assistant_teach_from_review_queue(
  p_unanswered_id uuid DEFAULT NULL,
  p_slug text DEFAULT NULL,
  p_title text DEFAULT NULL,
  p_category text DEFAULT 'process_explanation',
  p_department text DEFAULT 'general',
  p_summary text DEFAULT NULL,
  p_body text DEFAULT NULL,
  p_measurement_gotcha text DEFAULT NULL,
  p_official_source text DEFAULT NULL,
  p_screen_path text DEFAULT NULL,
  p_keywords text[] DEFAULT '{}'::text[],
  p_synonyms text[] DEFAULT '{}'::text[]
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := (SELECT auth.uid());
  v_lead_name text;
  v_dept_label text;
  v_kb_id uuid;
  v_expires timestamptz := now() + interval '90 days';
  v_slug text := LOWER(regexp_replace(btrim(COALESCE(p_slug, '')), '[^a-z0-9_]+', '_', 'g'));
BEGIN
  IF v_uid IS NULL OR NOT public.staff_assistant_crm_can_review() THEN
    RAISE EXCEPTION 'Not authorized: department lead or reviewer role required to teach Zoe.'
      USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(NULLIF(btrim(full_name), ''), 'Department Lead')
  INTO v_lead_name
  FROM public.profiles
  WHERE id = v_uid;

  v_dept_label := CASE LOWER(btrim(COALESCE(p_department, 'general')))
    WHEN 'tenant_ops' THEN 'Tenant Ops'
    WHEN 'landlord_ops' THEN 'Landlord Ops'
    WHEN 'calling_center' THEN 'Calling Center'
    WHEN 'agent_ops' THEN 'Agent Ops'
    WHEN 'partner_ops' THEN 'Partner Ops'
    WHEN 'financial_ops' THEN 'Financial Ops'
    WHEN 'hr' THEN 'HR'
    WHEN 'coo_ceo' THEN 'Operations Leadership'
    ELSE 'Operations'
  END;

  IF char_length(v_slug) < 3 THEN
    v_slug := 'taught_' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 12);
  END IF;

  INSERT INTO public.staff_assistant_knowledge_base (
    slug,
    title,
    category,
    department,
    summary,
    body,
    measurement_gotcha,
    official_source,
    screen_path,
    keywords,
    synonyms,
    review_status,
    reviewed_by,
    reviewed_by_name,
    reviewed_at,
    expires_at,
    updated_by,
    source_unanswered_id,
    updated_at
  )
  VALUES (
    left(v_slug, 80),
    btrim(COALESCE(p_title, 'Taught Knowledge Entry')),
    CASE
      WHEN p_category IN ('glossary', 'product_policy', 'process_explanation', 'where_to_find', 'measurement_gotcha')
      THEN p_category
      ELSE 'process_explanation'
    END,
    LOWER(btrim(COALESCE(p_department, 'general'))),
    btrim(COALESCE(p_summary, '')),
    btrim(COALESCE(p_body, '')),
    NULLIF(btrim(COALESCE(p_measurement_gotcha, '')), ''),
    NULLIF(btrim(COALESCE(p_official_source, '')), ''),
    NULLIF(btrim(COALESCE(p_screen_path, '')), ''),
    COALESCE(p_keywords, '{}'::text[]),
    COALESCE(p_synonyms, '{}'::text[]),
    'published',
    v_uid,
    COALESCE(v_lead_name, 'Department Lead') || ' (' || v_dept_label || ')',
    now(),
    v_expires,
    v_uid,
    p_unanswered_id,
    now()
  )
  ON CONFLICT (slug) DO UPDATE
  SET
    title = EXCLUDED.title,
    category = EXCLUDED.category,
    department = EXCLUDED.department,
    summary = EXCLUDED.summary,
    body = EXCLUDED.body,
    measurement_gotcha = EXCLUDED.measurement_gotcha,
    official_source = EXCLUDED.official_source,
    screen_path = EXCLUDED.screen_path,
    keywords = EXCLUDED.keywords,
    synonyms = EXCLUDED.synonyms,
    review_status = 'published',
    reviewed_by = v_uid,
    reviewed_by_name = EXCLUDED.reviewed_by_name,
    reviewed_at = now(),
    expires_at = v_expires,
    updated_by = v_uid,
    source_unanswered_id = COALESCE(EXCLUDED.source_unanswered_id, public.staff_assistant_knowledge_base.source_unanswered_id),
    updated_at = now()
  RETURNING id INTO v_kb_id;

  IF p_unanswered_id IS NOT NULL THEN
    UPDATE public.staff_assistant_unanswered
    SET
      status = 'resolved',
      reviewed_by = v_uid,
      reviewed_at = now(),
      review_note = 'Taught and published to knowledge base (' || v_slug || ')',
      taught_knowledge_id = v_kb_id,
      taught_by_name = COALESCE(v_lead_name, 'Department Lead') || ' (' || v_dept_label || ')',
      taught_at = now()
    WHERE id = p_unanswered_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'knowledge_id', v_kb_id,
    'slug', v_slug,
    'reviewed_by_name', COALESCE(v_lead_name, 'Department Lead') || ' (' || v_dept_label || ')',
    'reviewed_at', now(),
    'expires_at', v_expires
  );
END;
$$;

REVOKE ALL ON FUNCTION public.staff_assistant_teach_from_review_queue(uuid, text, text, text, text, text, text, text, text, text, text[], text[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.staff_assistant_teach_from_review_queue(uuid, text, text, text, text, text, text, text, text, text, text[], text[]) TO authenticated;

CREATE OR REPLACE FUNCTION public.assistant_staff_my_taught_updates()
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := (SELECT auth.uid());
  v_updates jsonb;
BEGIN
  IF v_uid IS NULL OR NOT public.staff_assistant_has_access() THEN
    RAISE EXCEPTION 'Not authorized: staff assistant access required.'
      USING ERRCODE = '42501';
  END IF;

  WITH rows AS (
    SELECT
      u.id AS unanswered_id,
      u.routed_department,
      COALESCE(u.taught_by_name, 'Department Lead') AS taught_by_name,
      u.taught_at,
      kb.slug,
      kb.title,
      kb.summary,
      kb.screen_path,
      kb.expires_at,
      ('Zoe learned this from ' || CASE u.routed_department
        WHEN 'tenant_ops' THEN 'Tenant Ops'
        WHEN 'landlord_ops' THEN 'Landlord Ops'
        WHEN 'calling_center' THEN 'Calling Center'
        WHEN 'agent_ops' THEN 'Agent Ops'
        WHEN 'partner_ops' THEN 'Partner Ops'
        WHEN 'financial_ops' THEN 'Financial Ops'
        WHEN 'hr' THEN 'HR'
        ELSE 'Operations'
      END) AS badge_label
    FROM public.staff_assistant_unanswered u
    JOIN public.staff_assistant_knowledge_base kb ON kb.id = u.taught_knowledge_id
    WHERE u.user_id = v_uid
      AND u.taught_knowledge_id IS NOT NULL
      AND u.taught_at >= (now() - interval '30 days')
    ORDER BY u.taught_at DESC
    LIMIT 10
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(rows)), '[]'::jsonb)
  INTO v_updates
  FROM rows;

  RETURN jsonb_build_object('updates', COALESCE(v_updates, '[]'::jsonb));
END;
$$;

REVOKE ALL ON FUNCTION public.assistant_staff_my_taught_updates() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.assistant_staff_my_taught_updates() TO authenticated;

-- 6. Role Goals & Official Measures Alongside Zoe Usage (`staff_assistant_role_goals_and_measures`)
CREATE OR REPLACE FUNCTION public.staff_assistant_role_goals_and_measures(
  p_days integer DEFAULT 14
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := (SELECT auth.uid());
  v_days integer := LEAST(GREATEST(COALESCE(p_days, 14), 1), 90);
  v_since timestamptz := (now() - make_interval(days => v_days));
  v_calls_curr bigint := 0;
  v_tasks_done_curr bigint := 0;
  v_verifications_curr bigint := 0;
  v_rows jsonb;
BEGIN
  IF v_uid IS NULL OR NOT public.staff_assistant_crm_can_review() THEN
    RAISE EXCEPTION 'Not authorized: manager or CRM reviewer role required.'
      USING ERRCODE = '42501';
  END IF;

  IF to_regclass('public.cc_call_attempts') IS NOT NULL THEN
    SELECT count(*) INTO v_calls_curr
    FROM public.cc_call_attempts
    WHERE COALESCE(recorded_at, created_at) >= v_since
      AND void_reason IS NULL;
  END IF;

  IF to_regclass('public.staff_tasks') IS NOT NULL THEN
    SELECT count(*) INTO v_tasks_done_curr
    FROM public.staff_tasks
    WHERE status = 'completed' AND COALESCE(completed_at, updated_at, created_at) >= v_since;
  END IF;

  IF to_regclass('public.rent_requests') IS NOT NULL THEN
    SELECT count(*) INTO v_verifications_curr
    FROM public.rent_requests
    WHERE COALESCE(updated_at, created_at) >= v_since
      AND status IN ('landlord_ops_approved', 'coo_approved', 'funded', 'disbursed', 'repaying');
  END IF;

  WITH role_catalog AS (
    SELECT * FROM (VALUES
      ('calling_center', 'Calling officers reach more tenants and landlords with prepared context', 'Official calls logged in Calling Center', v_calls_curr),
      ('tenant_ops', 'Tenant Ops spots early First 7 Days and arrears slippage faster', 'Rent Plans progressed / verified', v_verifications_curr),
      ('landlord_ops', 'Landlord Ops clears verification queues and locks payout numbers accurately', 'Landlord verifications completed', v_verifications_curr),
      ('agent_ops', 'Agent Ops re-engages silent collectors and tracks regional coverage', 'Completed operational tasks', v_tasks_done_curr),
      ('partner_ops', 'Partner Ops processes Supporter portfolios and Returns on schedule', 'Completed operational tasks', v_tasks_done_curr),
      ('financial_ops', 'Finance answers treasury, receivables, and payables questions without waiting', 'Completed operational tasks', v_tasks_done_curr),
      ('manager', 'Managers spot slipping work and desk bottlenecks early', 'Completed team tasks across workspace', v_tasks_done_curr),
      ('hr', 'HR resolves staff attendance, contract, and payroll queries faster', 'Completed staff tasks', v_tasks_done_curr)
    ) AS t(role_key, goal_statement, official_measure_label, official_measure_value)
  ),
  zoe_by_topic AS (
    SELECT
      l.topic,
      count(DISTINCT l.user_id) AS zoe_active_users,
      count(*) AS zoe_questions,
      ROUND(
        (count(*) FILTER (WHERE l.outcome = 'answered'))::numeric * 100.0
        / NULLIF(count(*)::numeric, 0),
        1
      ) AS zoe_answered_pct
    FROM public.staff_assistant_learning_log l
    WHERE l.created_at >= v_since
    GROUP BY l.topic
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'role_key', rc.role_key,
        'goal_statement', rc.goal_statement,
        'official_measure_label', rc.official_measure_label,
        'official_measure_value', rc.official_measure_value,
        'zoe_active_users', COALESCE(z.zoe_active_users, 0),
        'zoe_questions', COALESCE(z.zoe_questions, 0),
        'zoe_answered_pct', COALESCE(z.zoe_answered_pct, 0.0),
        'causality_disclaimer', 'Trend comparison only — does not claim Zoe caused a change in the operational measure.'
      )
    ),
    '[]'::jsonb
  )
  INTO v_rows
  FROM role_catalog rc
  LEFT JOIN zoe_by_topic z ON z.topic = rc.role_key;

  RETURN jsonb_build_object(
    'window_days', v_days,
    'disclaimer', 'Shows official Welile figures alongside Zoe usage trends; never claims causal attribution.',
    'roles', COALESCE(v_rows, '[]'::jsonb)
  );
END;
$$;

REVOKE ALL ON FUNCTION public.staff_assistant_role_goals_and_measures(integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.staff_assistant_role_goals_and_measures(integer) TO authenticated;


-- 7. Upgrade assistant_staff_search_knowledge_base with synonym expansion,
--    90-day review expiry awareness, usage_count tracking, and zero-hit logging
CREATE OR REPLACE FUNCTION public.assistant_staff_search_knowledge_base(
  p_query text DEFAULT '',
  p_category text DEFAULT NULL,
  p_limit integer DEFAULT 5
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := (SELECT auth.uid());
  v_clean_query text := left(btrim(COALESCE(p_query, '')), 240);
  v_expanded_query text;
  v_cat text := NULLIF(lower(btrim(COALESCE(p_category, ''))), '');
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 5), 1), 15);
  v_results jsonb := '[]'::jsonb;
  v_matched_ids uuid[] := '{}'::uuid[];
BEGIN
  IF v_uid IS NULL OR NOT public.staff_assistant_has_access() THEN
    RAISE EXCEPTION 'Not authorized: staff assistant access required.'
      USING ERRCODE = '42501';
  END IF;

  IF char_length(v_clean_query) < 2 THEN
    RETURN jsonb_build_object(
      'source', 'assistant_staff_search_knowledge_base',
      'query', v_clean_query,
      'entries', '[]'::jsonb
    );
  END IF;

  -- Synonym expansion for Welile domain terms
  v_expanded_query := v_clean_query;
  IF v_clean_query ILIKE '%overdue%' OR v_clean_query ILIKE '%late%' THEN
    v_expanded_query := v_expanded_query || ' arrears ageing';
  END IF;
  IF v_clean_query ILIKE '%cash%' OR v_clean_query ILIKE '%bank%' THEN
    v_expanded_query := v_expanded_query || ' treasury a1 a5 float';
  END IF;
  IF v_clean_query ILIKE '%partner%' OR v_clean_query ILIKE '%investor%' THEN
    v_expanded_query := v_expanded_query || ' supporter returns portfolio';
  END IF;
  IF v_clean_query ILIKE '%call%' OR v_clean_query ILIKE '%phone%' THEN
    v_expanded_query := v_expanded_query || ' calling center cc_call_attempts';
  END IF;

  WITH matched AS (
    SELECT
      kb.id,
      kb.slug,
      kb.title,
      kb.category,
      kb.department,
      kb.summary,
      kb.body,
      kb.measurement_gotcha,
      kb.official_source,
      kb.screen_path,
      kb.keywords,
      kb.synonyms,
      kb.reviewed_by_name,
      kb.reviewed_at,
      kb.expires_at,
      (kb.expires_at <= now()) AS review_expired,
      kb.usage_count,
      (
        COALESCE(ts_rank_cd(kb.search_tsv, websearch_to_tsquery('english', v_expanded_query)), 0)
        + CASE WHEN kb.title ILIKE ('%' || v_clean_query || '%') THEN 0.5 ELSE 0 END
        + CASE WHEN kb.slug ILIKE ('%' || replace(lower(v_clean_query), ' ', '_') || '%') THEN 0.4 ELSE 0 END
        + CASE WHEN EXISTS (
            SELECT 1 FROM unnest(kb.synonyms) s WHERE v_clean_query ILIKE ('%' || s || '%') OR s ILIKE ('%' || v_clean_query || '%')
          ) THEN 0.35 ELSE 0 END
        + CASE WHEN EXISTS (
            SELECT 1 FROM unnest(kb.keywords) k WHERE v_clean_query ILIKE ('%' || k || '%') OR k ILIKE ('%' || v_clean_query || '%')
          ) THEN 0.25 ELSE 0 END
      ) AS score
    FROM public.staff_assistant_knowledge_base kb
    WHERE kb.review_status = 'published'
      AND kb.expires_at > (now() - interval '30 days')
      AND (v_cat IS NULL OR kb.category = v_cat)
      AND (
        kb.search_tsv @@ websearch_to_tsquery('english', v_expanded_query)
        OR kb.title ILIKE ('%' || v_clean_query || '%')
        OR kb.summary ILIKE ('%' || v_clean_query || '%')
        OR EXISTS (
          SELECT 1 FROM unnest(kb.synonyms) s WHERE v_clean_query ILIKE ('%' || s || '%') OR s ILIKE ('%' || v_clean_query || '%')
        )
        OR EXISTS (
          SELECT 1 FROM unnest(kb.keywords) k WHERE v_clean_query ILIKE ('%' || k || '%') OR k ILIKE ('%' || v_clean_query || '%')
        )
      )
    ORDER BY score DESC, kb.usage_count DESC, kb.updated_at DESC
    LIMIT v_limit
  )
  SELECT
    COALESCE(array_agg(matched.id), '{}'::uuid[]),
    COALESCE(jsonb_agg(to_jsonb(matched)), '[]'::jsonb)
  INTO v_matched_ids, v_results
  FROM matched;

  RETURN jsonb_build_object(
    'source', 'assistant_staff_search_knowledge_base',
    'query', v_clean_query,
    'entries', v_results
  );
END;
$$;

REVOKE ALL ON FUNCTION public.assistant_staff_search_knowledge_base(text, text, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.assistant_staff_search_knowledge_base(text, text, integer) TO authenticated;


