)
VALUES
  ('glossary_rent_plan', 'Rent Plan (Regulatory Term)', 'glossary', 'tenant_ops', 'Welile pays the landlord upfront and the tenant repays daily over 7 to 120 days.', 'A Rent Plan is Welile''s core rental-finance product. Welile settles the landlord''s rent upfront and the tenant repays daily over 7 to 120 days. Always say Rent Plan (never loan) in all staff and customer communication.', 'Never count draft or pending requests as active Rent Plans; the repayment clock starts only on disbursement.', 'SYSTEM_CONTEXT.md §1.1', '/tenant-ops', ARRAY['rent plan', 'tenancy', 'repayment']::text[], ARRAY['rental plan', 'tenant plan', 'daily rent']::text[], 'published', 'Department Lead (' || 'tenant_ops' || ')', now(), now() + interval '90 days'),
  ('glossary_supporter', 'Supporter (Regulatory Term)', 'glossary', 'partner_ops', 'Capital partner who funds Rent Plans and receives Returns.', 'A Supporter is a retail or institutional capital partner who contributes funds to support Rent Plans and receives Returns. Always use Supporter (never lender or investor) in user-facing copy.', 'Supporter promissory notes are pledges until cash is actually collected and credited.', 'SYSTEM_CONTEXT.md §1.1', '/partner-ops', ARRAY['supporter', 'partner', 'capital']::text[], ARRAY['funder', 'partner ops', 'capital provider']::text[], 'published', 'Department Lead (' || 'partner_ops' || ')', now(), now() + interval '90 days'),
  ('glossary_returns', 'Returns (Supporter Payouts)', 'glossary', 'partner_ops', 'Approved earnings paid to Supporters on their active portfolios.', 'Returns are the scheduled payouts earned by Supporters on funded portfolios. Always use Returns (never ROI or interest) in all Welile communications and reports.', 'Support capacity uses operational float only, never withdrawable Returns.', 'SYSTEM_CONTEXT.md §1.1', '/partner-ops', ARRAY['returns', 'payout', 'supporter']::text[], ARRAY['supporter payout', 'portfolio earnings', 'reward']::text[], 'published', 'Department Lead (' || 'partner_ops' || ')', now(), now() + interval '90 days'),
  ('glossary_access_fee', 'Rent Access Fee Formula', 'glossary', 'financial_ops', 'Calculated as rent * (1.33^(days/30) - 1).', 'The Rent Access Fee is Welile''s fee for a Rent Plan, computed by the canonical formula rent * (1.33^(days/30) - 1) in compute_rent_repayment().', 'Never approximate access fees with flat linear percentages.', 'src/lib/rentCalculations.ts', '/tenant-ops', ARRAY['access fee', 'formula', 'repayment']::text[], ARRAY['service fee', 'plan fee', '33 percent']::text[], 'published', 'Department Lead (' || 'financial_ops' || ')', now(), now() + interval '90 days'),
  ('glossary_registration_fee', 'Registration Fee Tiers', 'glossary', 'tenant_ops', 'UGX 10,000 for rent <= UGX 200,000; UGX 20,000 above UGX 200,000.', 'New Rent Plans carry a Registration Fee of UGX 10,000 when principal rent is UGX 200,000 or less, and UGX 20,000 when principal rent exceeds UGX 200,000.', 'Reconciles together with Access Fee into the 4-part Platform Fee pool.', 'src/lib/rentCalculations.ts', '/tenant-ops', ARRAY['registration fee', 'onboarding fee', 'ugx 10000']::text[], ARRAY['reg fee', 'signup fee', 'ugx 20000']::text[], 'published', 'Department Lead (' || 'tenant_ops' || ')', now(), now() + interval '90 days'),
  ('glossary_account_a1', 'Account A1 — Cash and Bank', 'glossary', 'financial_ops', 'Spendable platform cash held in bank and primary mobile money treasury accounts.', 'Account A1 in the Welile Chart of Accounts represents verified Cash and Bank balances. Combined with A5 (Cash in Transit), A1 + A5 forms spendable Treasury Cash Position.', 'Never mix A2 (Agent Float) into A1 spendable treasury cash.', 'welile-chart-of-accounts', '/cfo/dashboard', ARRAY['a1', 'cash and bank', 'treasury']::text[], ARRAY['bank balance', 'momo treasury', 'spendable cash']::text[], 'published', 'Department Lead (' || 'financial_ops' || ')', now(), now() + interval '90 days'),
  ('glossary_account_a2', 'Account A2 — Agent Float', 'glossary', 'agent_ops', 'Operational float held by field agents for landlord payouts and collections.', 'Account A2 tracks Agent Float allocated to field agents. It is ring-fenced operational float and is reported separately from spendable Treasury Cash (A1 + A5).', 'Support capacity and float debits use operational float only, never withdrawable Returns.', 'welile-chart-of-accounts', '/agent-ops', ARRAY['a2', 'agent float', 'float']::text[], ARRAY['field float', 'operational float', 'agent wallet']::text[], 'published', 'Department Lead (' || 'agent_ops' || ')', now(), now() + interval '90 days'),
  ('glossary_account_a3', 'Account A3 — Rent Plan Receivables', 'glossary', 'financial_ops', 'Outstanding company Rent Plan receivables owed by tenants.', 'Account A3 tracks the company''s active Rent Plan receivables book. Agent lending (agents'' own money) is excluded from company Receivables.', 'Merchandise plans count as owed only if merchandise_plan_recovery_eligible passes.', 'welile-chart-of-accounts', '/cfo/dashboard', ARRAY['a3', 'receivables', 'rent book']::text[], ARRAY['money owed', 'tenant receivables', 'outstanding rent']::text[], 'published', 'Department Lead (' || 'financial_ops' || ')', now(), now() + interval '90 days'),
  ('glossary_account_a5', 'Account A5 — Cash in Transit', 'glossary', 'financial_ops', 'Verified collections and settlements in transit to primary treasury accounts.', 'Account A5 represents Cash in Transit that is part of spendable Treasury Cash Position (A1 + A5) in get_treasury_cash_position.', 'Always read get_treasury_cash_position rather than summing ledger legs manually.', 'welile-chart-of-accounts', '/cfo/dashboard', ARRAY['a5', 'cash in transit', 'settlement']::text[], ARRAY['in transit', 'pending settlement', 'treasury cash']::text[], 'published', 'Department Lead (' || 'financial_ops' || ')', now(), now() + interval '90 days'),
  ('glossary_account_a10', 'Account A10 — Advance Top-Up Legs', 'glossary', 'financial_ops', 'Advance top-up ledger classification in sofp_ledger_legs.', 'In sofp_ledger_legs, advance top-up legs are classified under Account A10 and emit no X4 leg for bucket_reclass pairs.', 'Approved by CFO accounting policy.', 'welile-chart-of-accounts', '/cfo/dashboard', ARRAY['a10', 'advance top up', 'sofp']::text[], ARRAY['bucket reclass', 'ledger legs', 'top up']::text[], 'published', 'Department Lead (' || 'financial_ops' || ')', now(), now() + interval '90 days'),
  ('glossary_pinned_daily_bill', 'Pinned Daily Bill (00:05 EAT)', 'glossary', 'tenant_ops', 'Daily expected repayment snapshot written to agent_expected_day_plans at 00:05 EAT.', 'At 00:05 EAT each Kampala day, the platform pins each active Rent Plan''s daily expected repayment into agent_expected_day_plans so intraday edits cannot distort collection coverage.', 'v_agent_daily_eligibility falls back to LEAST(daily_repayment, outstanding) only when no pinned bill exists today/yesterday.', 'SYSTEM_CONTEXT.md', '/tenant-ops', ARRAY['pinned bill', 'agent_expected_day_plans', '00:05 eat']::text[], ARRAY['daily bill', 'expected rent', 'daily quota']::text[], 'published', 'Department Lead (' || 'tenant_ops' || ')', now(), now() + interval '90 days'),
  ('glossary_am_plan_clock', 'AM Plan Clock (Active Rent Plan Clock)', 'glossary', 'tenant_ops', 'Authoritative repayment clock starting when a Rent Plan is disbursed.', 'The AM Plan Clock tracks elapsed repayment days and expected cumulative collections from the moment a Rent Plan is disbursed to the landlord.', 'Do not confuse pipeline stages (pending approval) with active AM Plan Clock plans.', 'SYSTEM_CONTEXT.md', '/tenant-ops', ARRAY['am_plan_clock', 'repayment clock', 'disbursed']::text[], ARRAY['plan clock', 'billing clock', 'active plan']::text[], 'published', 'Department Lead (' || 'tenant_ops' || ')', now(), now() + interval '90 days'),
  ('glossary_four_part_repayment', 'Four-Part Repayment Validation', 'glossary', 'financial_ops', 'Reconciles Returns + Agent Commission + Platform Fee to Access Fee + Registration Fee.', 'Every Rent Plan repayment split is validated so Supporter Returns + Agent Commission + Platform Fee equals the approved Access Fee + Registration Fee pool.', 'Enforced server-side to prevent fee leakage.', 'AGENTS.md', '/cfo/dashboard', ARRAY['four part repayment', 'platform fee', 'commission']::text[], ARRAY['repayment split', 'fee pool', '4 part validation']::text[], 'published', 'Department Lead (' || 'financial_ops' || ')', now(), now() + interval '90 days'),
  ('glossary_welile_homes', 'Welile Homes Full Management', 'glossary', 'landlord_ops', 'Full landlord rent management with a 10% management fee (2% agent / 8% Welile).', 'Welile Homes manages landlord properties end-to-end with guaranteed monthly payout and a 10% management fee split 2% to the collecting agent and 8% to Welile.', 'Welile Homes float moves strictly through wh_request_float and wh_cfo_disburse_float.', 'SYSTEM_CONTEXT.md §1.2', '/landlord-ops', ARRAY['welile homes', 'management fee', 'landlord']::text[], ARRAY['property management', 'wh float', 'guaranteed rent']::text[], 'published', 'Department Lead (' || 'landlord_ops' || ')', now(), now() + interval '90 days'),
  ('glossary_merchant_cashout', 'Merchant Cash-Out Network', 'glossary', 'financial_ops', 'Field agents settle withdrawals in cash for a 0.5% commission on settled principal.', 'In the Merchant Cash-Out network, vetted agents front mobile money or cash to settle approved withdrawals and earn 0.5% commission on settled principal.', 'Merchant desks exclude Welile Homes float requests.', 'SYSTEM_CONTEXT.md §1.2', '/financial-ops', ARRAY['merchant cashout', '0.5%', 'withdrawal']::text[], ARRAY['cash out', 'merchant agent', 'settlement']::text[], 'published', 'Department Lead (' || 'financial_ops' || ')', now(), now() + interval '90 days'),
  ('glossary_kampala_day', 'Kampala Day (Africa/Kampala UTC+3)', 'glossary', 'general', 'All daily and 7-day Welile reports anchor on Africa/Kampala midnight-to-midnight.', 'Every Welile daily report, 7-day CFO report, and Zoe rate limit uses Africa/Kampala (UTC+3) calendar days via src/lib/kampalaDays.ts.', 'Never group Kampala business days by UTC midnight.', 'src/lib/kampalaDays.ts', '/me', ARRAY['kampala day', 'eat', 'timezone']::text[], ARRAY['utc+3', 'africa kampala', 'reporting day']::text[], 'published', 'Department Lead (' || 'general' || ')', now(), now() + interval '90 days'),
  ('glossary_calling_week', 'Calling Center Week (Wednesday–Tuesday)', 'glossary', 'calling_center', 'My Space Calling & Pipeline Feedback reports run across Wednesday–Tuesday Kampala weeks.', 'Staff calling reports in My Space (/me/reports and /me/staff-reports) aggregate across Wednesday-to-Tuesday Kampala weeks as well as calendar months.', 'Reads only staff_calling_detailed_report(p_from, p_to).', 'AGENTS.md', '/me/reports', ARRAY['wednesday tuesday', 'calling week', 'staff_calling_detailed_report']::text[], ARRAY['weekly calling', 'jane winnie hanisha', 'call week']::text[], 'published', 'Department Lead (' || 'calling_center' || ')', now(), now() + interval '90 days'),
  ('glossary_first_seven_days', 'First 7 Days Cohort Report', 'glossary', 'tenant_ops', 'Tracks newly funded Rent Plans across their first 7 days of daily repayment.', 'The First 7 Days report in Tenant Ops measures expected, collected, and uncollected UGX across Days 1 to 7 of newly funded Rent Plans to catch early onboarding defaults.', 'Uncollected = Expected - Collected across the 7-day cohort.', 'assistant_staff_tops_first_seven_summary', '/tenant-ops', ARRAY['first 7 days', 'onboarding', 'cohort']::text[], ARRAY['first seven days', 'new plans', 'early repayment']::text[], 'published', 'Department Lead (' || 'tenant_ops' || ')', now(), now() + interval '90 days'),
  ('glossary_arrears_ageing', 'Arrears Ageing Buckets (1-7, 8-14, 15-30, 30+)', 'glossary', 'tenant_ops', 'Groups overdue Rent Plans by days in arrears: 1-7, 8-14, 15-30, and 30+ days.', 'The Tenant Ops Arrears Ageing report groups overdue Rent Plans into four buckets (1-7, 8-14, 15-30, and 30+ days) and reports both bucket totals and total_arrears_ugx.', 'Always cite the as_at date when reporting ageing totals.', 'assistant_staff_tops_arrears_ageing', '/tenant-ops', ARRAY['arrears ageing', 'buckets', '30+ days']::text[], ARRAY['overdue buckets', 'ageing report', '1-7 8-14 15-30']::text[], 'published', 'Department Lead (' || 'tenant_ops' || ')', now(), now() + interval '90 days'),
  ('glossary_silent_collectors', 'Silent Field Collectors', 'glossary', 'agent_ops', 'Agents with active Rent Plans who have recorded zero collections for N consecutive days.', 'The Silent Collectors report identifies field agents who hold active Rent Plans with expected daily bills but have logged no collections for at least N days (default 3 days).', 'Used by Agent Ops to prioritize field follow-ups.', 'assistant_staff_aops_silent_collectors', '/agent-ops', ARRAY['silent collectors', 'inactive agents', 'zero collections']::text[], ARRAY['silent agents', 'non collecting agents', 'field follow up']::text[], 'published', 'Department Lead (' || 'agent_ops' || ')', now(), now() + interval '90 days'),
  ('kb_tenant_ops_workspace_navigation', 'Where to Find Tenant Ops Reports and Queues', 'where_to_find', 'tenant_ops', 'Open /tenant-ops in your Welile workspace to access live Tenant Ops queues, filters, and certified exports.', 'Staff with the tenant_ops role can open /tenant-ops from the left navigation rail or mobile bottom menu. In Zoe, you can also ask for the latest Tenant Ops summary and click Show the data to inspect the exact table rows.', 'Requires active tenant_ops role and two-step login (MFA AAL2) for sensitive department figures.', 'SYSTEM_CONTEXT.md (Tenant Ops)', '/tenant-ops', ARRAY['tenant_ops', 'tenant ops', 'where to find', 'screen', 'navigation']::text[], ARRAY['find tenant ops', 'tenant ops page', 'tenant ops dashboard']::text[], 'published', 'Department Lead (' || 'tenant_ops' || ')', now(), now() + interval '90 days'),
  ('kb_tenant_ops_daily_workflow', 'Tenant Ops Daily Morning Review Workflow', 'process_explanation', 'tenant_ops', 'How Tenant Ops staff review overnight changes, clear priority queues, and log outcomes each Kampala day.', 'Each morning (Africa/Kampala time), Tenant Ops officers check the Morning Brief in My Space, open /tenant-ops to sort pending items by age on desk, and verify that all actions follow the read-only verification checklist before escalating exceptions.', 'All daily cutoffs run on Africa/Kampala (UTC+3) calendar days, never UTC midnight.', 'SYSTEM_CONTEXT.md (Tenant Ops)', '/tenant-ops', ARRAY['tenant_ops', 'workflow', 'daily checklist', 'morning review']::text[], ARRAY['tenant ops process', 'tenant ops routine', 'how tenant ops works']::text[], 'published', 'Department Lead (' || 'tenant_ops' || ')', now(), now() + interval '90 days'),
  ('kb_tenant_ops_verification_controls', 'Tenant Ops Verification and Approval Controls', 'process_explanation', 'tenant_ops', 'Role-gated verification steps and maker-checker rules in Tenant Ops.', 'In Tenant Ops, every record transition is enforced by server-side SECURITY DEFINER RPCs. Zoe is strictly read-only and never approves, edits, or moves money; to complete an approval or stage transition, use /tenant-ops.', 'Senders cannot self-approve their own submissions; stage approvals filter on expected current status.', 'SYSTEM_CONTEXT.md (Tenant Ops)', '/tenant-ops', ARRAY['tenant_ops', 'verification', 'approval', 'controls', 'maker checker']::text[], ARRAY['approve tenant ops', 'tenant ops rules', 'tenant ops permissions']::text[], 'published', 'Department Lead (' || 'tenant_ops' || ')', now(), now() + interval '90 days'),
  ('kb_tenant_ops_metric_reconciliation', 'Tenant Ops Official Metric Reconciliation Rules', 'measurement_gotcha', 'tenant_ops', 'How official Tenant Ops totals reconcile and why ad-hoc filters can differ from headline cards.', 'Headline cards on /tenant-ops read certified server RPCs over the full authorized dataset. When Zoe runs an ad-hoc query on zoe_ro views, she labels it "Ad hoc, not certified" so staff never confuse a filtered slice with the certified headline report.', 'Always compare like-for-like date windows (Kampala days) and exclude reversed or deleted_by_agent rows.', 'SYSTEM_CONTEXT.md (Tenant Ops)', '/tenant-ops', ARRAY['tenant_ops', 'reconciliation', 'gotcha', 'official figures']::text[], ARRAY['tenant ops numbers disagree', 'tenant ops discrepancy', 'tenant ops total']::text[], 'published', 'Department Lead (' || 'tenant_ops' || ')', now(), now() + interval '90 days'),
  ('kb_tenant_ops_regulatory_terminology', 'Tenant Ops Mandatory Regulatory Terminology & Privacy Rules', 'product_policy', 'tenant_ops', 'Mandatory use of Rent Plan, Supporter, Returns, UGX formatting, and PII masking in Tenant Ops.', 'All staff and Zoe outputs in Tenant Ops must use "Rent Plan" (never loan), "Supporter" (never lender), and "Returns" (never ROI or interest). Currency is always formatted as "UGX 1,234". Phone numbers and National IDs are masked unless the caller holds explicit PII permission.', 'Outbound emails from Zoe can only be sent to verified Welile staff email addresses after a human click.', 'SYSTEM_CONTEXT.md (Tenant Ops)', '/tenant-ops', ARRAY['tenant_ops', 'terminology', 'privacy', 'masking', 'ugx']::text[], ARRAY['tenant ops policy', 'tenant ops compliance', 'tenant ops terms']::text[], 'published', 'Department Lead (' || 'tenant_ops' || ')', now(), now() + interval '90 days'),
  ('kb_landlord_ops_workspace_navigation', 'Where to Find Landlord Ops Reports and Queues', 'where_to_find', 'landlord_ops', 'Open /landlord-ops in your Welile workspace to access live Landlord Ops queues, filters, and certified exports.', 'Staff with the landlord_ops role can open /landlord-ops from the left navigation rail or mobile bottom menu. In Zoe, you can also ask for the latest Landlord Ops summary and click Show the data to inspect the exact table rows.', 'Requires active landlord_ops role and two-step login (MFA AAL2) for sensitive department figures.', 'SYSTEM_CONTEXT.md (Landlord Ops)', '/landlord-ops', ARRAY['landlord_ops', 'landlord ops', 'where to find', 'screen', 'navigation']::text[], ARRAY['find landlord ops', 'landlord ops page', 'landlord ops dashboard']::text[], 'published', 'Department Lead (' || 'landlord_ops' || ')', now(), now() + interval '90 days'),
  ('kb_landlord_ops_daily_workflow', 'Landlord Ops Daily Morning Review Workflow', 'process_explanation', 'landlord_ops', 'How Landlord Ops staff review overnight changes, clear priority queues, and log outcomes each Kampala day.', 'Each morning (Africa/Kampala time), Landlord Ops officers check the Morning Brief in My Space, open /landlord-ops to sort pending items by age on desk, and verify that all actions follow the read-only verification checklist before escalating exceptions.', 'All daily cutoffs run on Africa/Kampala (UTC+3) calendar days, never UTC midnight.', 'SYSTEM_CONTEXT.md (Landlord Ops)', '/landlord-ops', ARRAY['landlord_ops', 'workflow', 'daily checklist', 'morning review']::text[], ARRAY['landlord ops process', 'landlord ops routine', 'how landlord ops works']::text[], 'published', 'Department Lead (' || 'landlord_ops' || ')', now(), now() + interval '90 days'),
  ('kb_landlord_ops_verification_controls', 'Landlord Ops Verification and Approval Controls', 'process_explanation', 'landlord_ops', 'Role-gated verification steps and maker-checker rules in Landlord Ops.', 'In Landlord Ops, every record transition is enforced by server-side SECURITY DEFINER RPCs. Zoe is strictly read-only and never approves, edits, or moves money; to complete an approval or stage transition, use /landlord-ops.', 'Senders cannot self-approve their own submissions; stage approvals filter on expected current status.', 'SYSTEM_CONTEXT.md (Landlord Ops)', '/landlord-ops', ARRAY['landlord_ops', 'verification', 'approval', 'controls', 'maker checker']::text[], ARRAY['approve landlord ops', 'landlord ops rules', 'landlord ops permissions']::text[], 'published', 'Department Lead (' || 'landlord_ops' || ')', now(), now() + interval '90 days'),
  ('kb_landlord_ops_metric_reconciliation', 'Landlord Ops Official Metric Reconciliation Rules', 'measurement_gotcha', 'landlord_ops', 'How official Landlord Ops totals reconcile and why ad-hoc filters can differ from headline cards.', 'Headline cards on /landlord-ops read certified server RPCs over the full authorized dataset. When Zoe runs an ad-hoc query on zoe_ro views, she labels it "Ad hoc, not certified" so staff never confuse a filtered slice with the certified headline report.', 'Always compare like-for-like date windows (Kampala days) and exclude reversed or deleted_by_agent rows.', 'SYSTEM_CONTEXT.md (Landlord Ops)', '/landlord-ops', ARRAY['landlord_ops', 'reconciliation', 'gotcha', 'official figures']::text[], ARRAY['landlord ops numbers disagree', 'landlord ops discrepancy', 'landlord ops total']::text[], 'published', 'Department Lead (' || 'landlord_ops' || ')', now(), now() + interval '90 days'),
  ('kb_landlord_ops_regulatory_terminology', 'Landlord Ops Mandatory Regulatory Terminology & Privacy Rules', 'product_policy', 'landlord_ops', 'Mandatory use of Rent Plan, Supporter, Returns, UGX formatting, and PII masking in Landlord Ops.', 'All staff and Zoe outputs in Landlord Ops must use "Rent Plan" (never loan), "Supporter" (never lender), and "Returns" (never ROI or interest). Currency is always formatted as "UGX 1,234". Phone numbers and National IDs are masked unless the caller holds explicit PII permission.', 'Outbound emails from Zoe can only be sent to verified Welile staff email addresses after a human click.', 'SYSTEM_CONTEXT.md (Landlord Ops)', '/landlord-ops', ARRAY['landlord_ops', 'terminology', 'privacy', 'masking', 'ugx']::text[], ARRAY['landlord ops policy', 'landlord ops compliance', 'landlord ops terms']::text[], 'published', 'Department Lead (' || 'landlord_ops' || ')', now(), now() + interval '90 days'),
  ('kb_calling_center_workspace_navigation', 'Where to Find Calling Center Reports and Queues', 'where_to_find', 'calling_center', 'Open /me/reports in your Welile workspace to access live Calling Center queues, filters, and certified exports.', 'Staff with the calling_center role can open /me/reports from the left navigation rail or mobile bottom menu. In Zoe, you can also ask for the latest Calling Center summary and click Show the data to inspect the exact table rows.', 'Requires active calling_center role and two-step login (MFA AAL2) for sensitive department figures.', 'SYSTEM_CONTEXT.md (Calling Center)', '/me/reports', ARRAY['calling_center', 'calling center', 'where to find', 'screen', 'navigation']::text[], ARRAY['find calling center', 'calling center page', 'calling center dashboard']::text[], 'published', 'Department Lead (' || 'calling_center' || ')', now(), now() + interval '90 days'),
  ('kb_calling_center_daily_workflow', 'Calling Center Daily Morning Review Workflow', 'process_explanation', 'calling_center', 'How Calling Center staff review overnight changes, clear priority queues, and log outcomes each Kampala day.', 'Each morning (Africa/Kampala time), Calling Center officers check the Morning Brief in My Space, open /me/reports to sort pending items by age on desk, and verify that all actions follow the read-only verification checklist before escalating exceptions.', 'All daily cutoffs run on Africa/Kampala (UTC+3) calendar days, never UTC midnight.', 'SYSTEM_CONTEXT.md (Calling Center)', '/me/reports', ARRAY['calling_center', 'workflow', 'daily checklist', 'morning review']::text[], ARRAY['calling center process', 'calling center routine', 'how calling center works']::text[], 'published', 'Department Lead (' || 'calling_center' || ')', now(), now() + interval '90 days'),
  ('kb_calling_center_verification_controls', 'Calling Center Verification and Approval Controls', 'process_explanation', 'calling_center', 'Role-gated verification steps and maker-checker rules in Calling Center.', 'In Calling Center, every record transition is enforced by server-side SECURITY DEFINER RPCs. Zoe is strictly read-only and never approves, edits, or moves money; to complete an approval or stage transition, use /me/reports.', 'Senders cannot self-approve their own submissions; stage approvals filter on expected current status.', 'SYSTEM_CONTEXT.md (Calling Center)', '/me/reports', ARRAY['calling_center', 'verification', 'approval', 'controls', 'maker checker']::text[], ARRAY['approve calling center', 'calling center rules', 'calling center permissions']::text[], 'published', 'Department Lead (' || 'calling_center' || ')', now(), now() + interval '90 days'),
