  ('kb_coo_ceo_regulatory_terminology', 'Operations Leadership Mandatory Regulatory Terminology & Privacy Rules', 'product_policy', 'coo_ceo', 'Mandatory use of Rent Plan, Supporter, Returns, UGX formatting, and PII masking in Operations Leadership.', 'All staff and Zoe outputs in Operations Leadership must use "Rent Plan" (never loan), "Supporter" (never lender), and "Returns" (never ROI or interest). Currency is always formatted as "UGX 1,234". Phone numbers and National IDs are masked unless the caller holds explicit PII permission.', 'Outbound emails from Zoe can only be sent to verified Welile staff email addresses after a human click.', 'SYSTEM_CONTEXT.md (Operations Leadership)', '/coo/dashboard', ARRAY['coo_ceo', 'terminology', 'privacy', 'masking', 'ugx']::text[], ARRAY['operations leadership policy', 'operations leadership compliance', 'operations leadership terms']::text[], 'published', 'Department Lead (' || 'coo_ceo' || ')', now(), now() + interval '90 days'),
  ('where_to_find_calling_tenants', 'Where to Go When You Want to Call Tenants', 'where_to_find', 'calling_center', 'Open the Tenant Ops Calling Center (/tenant-ops or /crm/autocall) to call tenants from the deduplicated queue.', 'To call tenants, open the Tenant Ops workspace (/tenant-ops) and select the Calling Center tab, or open /me/reports to review your Calling & Pipeline Feedback report. The queue deduplicates contacts and logs every call outcome.', 'Calls logged within 15 minutes to the same tenant are deduplicated in reporting.', 'SYSTEM_CONTEXT.md', '/tenant-ops', ARRAY['call tenants', 'where do i go', 'calling center', 'tenant queue']::text[], ARRAY['if i want to call tenants where do i go', 'phone tenants', 'tenant calling screen']::text[], 'published', 'Department Lead (' || 'calling_center' || ')', now(), now() + interval '90 days'),
  ('where_to_find_tenants_lists', 'How to Find Tenants Lists and Filter by Stage or City', 'where_to_find', 'tenant_ops', 'Use Tenant Ops (/tenant-ops) or ask Zoe to search tenants or group Rent Plans by city and stage.', 'To view or filter tenant lists, open /tenant-ops where you can filter by Rent Plan stage, city, arrears bucket, or repayment status. In Zoe, you can ask to find a tenant by name or query zoe_ro.tenants_directory_by_stage_and_location for city and stage breakdowns.', 'Phone numbers are masked (+256 7•• ••• 123) for roles without full PII access.', 'assistant_staff_tops_find_tenant', '/tenant-ops', ARRAY['tenants lists', 'find tenant', 'tenant directory', 'filter tenants']::text[], ARRAY['i want guidance on finding tenants lists', 'where is tenant list', 'search tenants']::text[], 'published', 'Department Lead (' || 'tenant_ops' || ')', now(), now() + interval '90 days'),
  ('where_to_find_my_calls_this_week', 'How to Check Your Own Calls for This Week', 'where_to_find', 'calling_center', 'Ask Zoe "Show my own calls for this week" or open /me/reports in My Space.', 'You can check your own calling activity at any time by opening /me/reports in My Space or asking Zoe "Show my own calls for this week" (which runs assistant_staff_my_calls or assistant_staff_my_work_summary across the current Kampala week).', 'Calling Center weekly reports use Wednesday-to-Tuesday Kampala weeks.', 'assistant_staff_my_calls', '/me/reports', ARRAY['my own calls', 'calls this week', 'my space reports']::text[], ARRAY['show my own calls for this week', 'my call count', 'calls logged today']::text[], 'published', 'Department Lead (' || 'calling_center' || ')', now(), now() + interval '90 days'),
  ('gotcha_expected_vs_collected_ratio', 'Why Total Cash Collected Cannot Be Divided by Today Pinned Expected Bill', 'measurement_gotcha', 'financial_ops', 'Total cash collected includes arrears from prior days; dividing it by today''s pinned bill overstates coverage by ~2x.', 'In Welile collection reporting, agent_expected_day_plans pins today''s scheduled bill at 00:05 EAT, while agent_collections includes both on-schedule payments for today''s bill and arrears recoveries from earlier days. True on-schedule coverage divides only collected_on_schedule_ugx by expected_pinned_ugx.', 'Always report expected_pinned_ugx, collected_on_schedule_ugx, collected_arrears_ugx, and total_cash_collected_ugx separately.', 'zoe_ro.operations_daily_collection_coverage', '/coo/dashboard', ARRAY['expected vs collected', 'coverage ratio', 'pinned bill', 'arrears']::text[], ARRAY['collection rate over 100%', 'why is collection coverage different', 'on schedule coverage']::text[], 'published', 'Department Lead (' || 'financial_ops' || ')', now(), now() + interval '90 days'),
  ('gotcha_treasury_cash_vs_agent_float', 'Why Agent Float (A2) Is Excluded from Spendable Treasury Cash (A1 + A5)', 'measurement_gotcha', 'financial_ops', 'Spendable Treasury Cash is A1 + A5 only; A2 Agent Float is already allocated to field agents.', 'get_treasury_cash_position reports Spendable Treasury Cash (Account A1 Cash & Bank + Account A5 Cash in Transit) separately from Account A2 (Agent Float). A2 is held by field agents for landlord payouts and cannot be spent on company requisitions.', 'Never add A2 to A1 + A5 when answering how much cash Welile has available.', 'get_treasury_cash_position', '/cfo/dashboard', ARRAY['treasury cash', 'agent float', 'a1 a5 a2', 'spendable cash']::text[], ARRAY['cash position discrepancy', 'how much cash do we have', 'available treasury']::text[], 'published', 'Department Lead (' || 'financial_ops' || ')', now(), now() + interval '90 days'),
  ('tool_guide_my_profile', 'My Space Profile & Role Summary', 'where_to_find', 'hr', 'Checking your own staff profile, department, and active roles in My Space.', 'Checking your own staff profile, department, and active roles in My Space. Open /me in the Welile app to take action, or ask Zoe for a read-only summary citing assistant_staff_my_profile.', 'Read-only via assistant_staff_my_profile; respects caller role and MFA AAL2 gates.', 'assistant_staff_my_profile', '/me', ARRAY['my profile', 'hr', 'assistant_staff_my_profile', 'report']::text[], ARRAY['my space profile & role summary', 'how to check my profile', 'my profile in welile']::text[], 'published', 'Department Lead (' || 'hr' || ')', now(), now() + interval '90 days'),
  ('faq_my_profile_interpretation', 'How to Interpret My Space Profile & Role Summary Figures', 'measurement_gotcha', 'hr', 'Key measurement rules when reading My Space Profile & Role Summary (assistant_staff_my_profile).', 'When reviewing My Space Profile & Role Summary, always verify the Kampala date range (Periodpill) and official source (assistant_staff_my_profile). Figures come directly from the server RPC without browser-side estimation.', 'Never mix assistant_staff_my_profile totals with unverified external spreadsheets.', 'assistant_staff_my_profile', '/me', ARRAY['my profile', 'interpretation', 'measurement', 'hr']::text[], ARRAY['explain my space profile & role summary', 'meaning of my profile']::text[], 'published', 'Department Lead (' || 'hr' || ')', now(), now() + interval '90 days'),
  ('sop_my_profile_action_screen', 'Which Screen to Use When Acting on My Space Profile & Role Summary', 'where_to_find', 'hr', 'Use /me to perform any operational action related to My Space Profile & Role Summary.', 'Because Zoe follows the CEO''s strict read-only rule, she never modifies Welile records. After checking My Space Profile & Role Summary in Zoe, navigate to /me to record calls, update tasks, or submit approvals.', 'Zoe will always name /me if asked to mutate records covered by assistant_staff_my_profile.', 'assistant_staff_my_profile', '/me', ARRAY['my profile', 'screen', 'action', '/me']::text[], ARRAY['where to edit my profile', 'screen for my space profile & role summary']::text[], 'published', 'Department Lead (' || 'hr' || ')', now(), now() + interval '90 days'),
  ('tool_guide_my_payslips', 'My Space Payslips & Net Pay History', 'where_to_find', 'hr', 'Viewing your own monthly payslips, gross pay, statutory deductions, and net pay in UGX.', 'Viewing your own monthly payslips, gross pay, statutory deductions, and net pay in UGX. Open /me/payslips in the Welile app to take action, or ask Zoe for a read-only summary citing assistant_staff_my_payslips.', 'Read-only via assistant_staff_my_payslips; respects caller role and MFA AAL2 gates.', 'assistant_staff_my_payslips', '/me/payslips', ARRAY['my payslips', 'hr', 'assistant_staff_my_payslips', 'report']::text[], ARRAY['my space payslips & net pay history', 'how to check my payslips', 'my payslips in welile']::text[], 'published', 'Department Lead (' || 'hr' || ')', now(), now() + interval '90 days'),
